8	import { getDb } from '../db';
9	import { violationPatterns, truthDriftTimeSeries, personaAlignmentMap } from '../../drizzle/schema';
10	import { eq, desc, and, sql } from 'drizzle-orm';
11	import { governedGenerate } from "../governance/governed-generate";
12	import { generalLog } from '../_core/logger';
