73	/**
74	 * Record resolution of a violation (auto-fixed, manual, or reverted).
75	 */
76	export async function recordPatternResolution(
77	  violationType: string,
78	  surface: string,
79	  resolution: 'auto_fixed' | 'manual_fixed' | 'reverted',
80	): Promise<void> {
81	  const db = await getDb();
82	  if (!db) return;
83	  const existing = await db.select()
84	    .from(violationPatterns)
85	    .where(
86	      and(
87	        eq(violationPatterns.violationType, violationType),
88	        eq(violationPatterns.surface, surface),
89	      )
90	    )
91	    .limit(1);
92	  
93	  if (existing.length > 0) {
94	    const updates: Record<string, unknown> = { updatedAt: new Date() };
95	    if (resolution === 'auto_fixed') {
96	      updates.autoFixedCount = sql`${violationPatterns.autoFixedCount} + 1`;
97	    } else if (resolution === 'manual_fixed') {
98	      updates.manualFixedCount = sql`${violationPatterns.manualFixedCount} + 1`;
99	    } else if (resolution === 'reverted') {
100	      updates.revertedCount = sql`${violationPatterns.revertedCount} + 1`;
101	    }
102	    await db.update(violationPatterns)
103	      .set(updates)
104	      .where(eq(violationPatterns.id, existing[0].id));
105	  }
106	}
