185	/**
186	 * Generate prevention advice for a pattern using Claude.
187	 */
188	export async function generatePreventionAdvice(patternId: string): Promise<string> {
189	  const db = await getDb();
190	  if (!db) return 'Database not available.';
191	  const pattern = await db.select()
192	    .from(violationPatterns)
193	    .where(eq(violationPatterns.patternId, patternId))
194	    .limit(1);
195	  
196	  if (pattern.length === 0) return 'Pattern not found.';
197	  
198	  const p = pattern[0];
199	  const govResult = await governedGenerate({
200	    messages: [
201	      {
202	        role: 'system',
203	        content: 'You are a governance advisor. Given a recurring violation pattern, suggest a concrete prevention strategy in 2-3 sentences.',
204	      },
205	      {
206	        role: 'user',
207	        content: `Violation type: ${p.violationType}\nSurface: ${p.surface}\nOccurrences: ${p.occurrenceCount}\nAuto-fixed: ${p.autoFixedCount}\nManual-fixed: ${p.manualFixedCount}\nReverted: ${p.revertedCount}\nSample content: ${p.commonContent || 'N/A'}\n\nWhat should be done to prevent this from recurring?`,
208	      },
209	    ],
210	    contentType: 'generation',
211	    contentRole: 'user-facing',
212	    productId: 'services',
213	    surfaceId: 'services-organizational-memory',
214	  });
215	  
216	  const rawAdvice = (govResult as unknown as Record<string, unknown>).choices?.[0]?.message?.content;
217	  const advice = typeof rawAdvice === 'string' ? rawAdvice : 'Unable to generate advice.';
218	  
219	  // Persist the advice
220	  await db.update(violationPatterns)
221	    .set({ suggestedPrevention: advice, updatedAt: new Date() })
222	    .where(eq(violationPatterns.patternId, patternId));
223	  
224	  return advice as string;
225	}
