227	// ============================================================================
228	// HISTORICAL DRIFT MODEL
229	// ============================================================================
230	
231	interface DriftSnapshot {
232	  scanId?: string;
233	  truthDriftScore: number;
234	  totalPages: number;
235	  passedPages: number;
236	  flaggedPages: number;
237	  blockedPages: number;
238	  totalViolations: number;
239	  criticalViolations: number;
240	  violationsByType?: Record<string, number>;
241	  autoAppliedCount?: number;
242	  queuedCount?: number;
243	  revertedCount?: number;
244	  activeProfile?: string;
245	  autoApplyEnabled?: boolean;
246	}
247	
248	/**
249	 * Record a truth-drift snapshot after a scan.
250	 * Automatically calculates trend and delta from previous snapshot.
251	 */
252	export async function recordDriftSnapshot(snapshot: DriftSnapshot): Promise<{
253	  snapshotId: string;
254	  trend: string;
255	  delta: number | null;
256	}> {
257	  const db = await getDb();
258	  if (!db) return { snapshotId: '', trend: 'unknown', delta: null };
259	  // Get previous snapshot for trend calculation
260	  const previous = await db.select()
261	    .from(truthDriftTimeSeries)
262	    .orderBy(desc(truthDriftTimeSeries.capturedAt))
263	    .limit(1);
264	  
265	  const previousScore = previous.length > 0 ? previous[0].truthDriftScore : null;
266	  let trend = 'stable';
267	  let delta: number | null = null;
268	  
269	  if (previousScore !== null) {
270	    delta = snapshot.truthDriftScore - previousScore;
271	    if (delta > 2) trend = 'improving';
272	    else if (delta < -2) trend = 'declining';
273	    else trend = 'stable';
274	  }
275	  
276	  const snapshotId = `drift_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
277	  
278	  await db.insert(truthDriftTimeSeries).values({
279	    snapshotId,
280	    scanId: snapshot.scanId,
281	    truthDriftScore: snapshot.truthDriftScore,
282	    totalPages: snapshot.totalPages,
283	    passedPages: snapshot.passedPages,
284	    flaggedPages: snapshot.flaggedPages,
285	    blockedPages: snapshot.blockedPages,
286	    totalViolations: snapshot.totalViolations,
287	    criticalViolations: snapshot.criticalViolations,
288	    violationsByType: snapshot.violationsByType,
289	    autoAppliedCount: snapshot.autoAppliedCount || 0,
290	    queuedCount: snapshot.queuedCount || 0,
291	    revertedCount: snapshot.revertedCount || 0,
292	    previousScore: previousScore,
293	    trend,
294	    weekOverWeekDelta: delta,
295	    activeProfile: snapshot.activeProfile,
296	    autoApplyEnabled: snapshot.autoApplyEnabled,
297	  });
298	  
299	  return { snapshotId, trend, delta };
300	}
