604	// ============================================================================
605	// INTEGRATION: Wire into scanner post-scan hook
606	// ============================================================================
607	
608	/**
609	 * Post-scan hook: record all violations and drift snapshot.
610	 * Call this after every scan to build the organizational memory.
611	 */
612	export async function postScanMemoryUpdate(scanReport: {
613	  scanId: string;
614	  totalPages: number;
615	  passedPages: number;
616	  flaggedPages: number;
617	  blockedPages: number;
618	  totalViolations: number;
619	  criticalViolations: number;
620	  violations: Array<{ violationType: string; route: string; severity: string; content?: string }>;
621	  autoAppliedCount?: number;
622	  queuedCount?: number;
623	  activeProfile?: string;
624	  autoApplyEnabled?: boolean;
625	}): Promise<{
626	  patternsUpdated: number;
627	  newPatterns: number;
628	  driftSnapshot: { snapshotId: string; trend: string; delta: number | null };
629	}> {
630	  // 1. Record violation patterns for cross-surface learning
631	  const patternResult = await recordScanViolations(scanReport.violations, 'website');
632	  
633	  // 2. Calculate truth-drift score
634	  const truthDriftScore = scanReport.totalPages > 0
635	    ? Math.round((scanReport.passedPages / scanReport.totalPages) * 100)
636	    : 100;
637	  
638	  // 3. Build violation type breakdown
639	  const violationsByType: Record<string, number> = {};
640	  for (const v of scanReport.violations) {
641	    violationsByType[v.violationType] = (violationsByType[v.violationType] || 0) + 1;
642	  }
643	  
644	  // 4. Record drift snapshot
645	  const driftSnapshot = await recordDriftSnapshot({
646	    scanId: scanReport.scanId,
647	    truthDriftScore,
648	    totalPages: scanReport.totalPages,
649	    passedPages: scanReport.passedPages,
650	    flaggedPages: scanReport.flaggedPages,
651	    blockedPages: scanReport.blockedPages,
652	    totalViolations: scanReport.totalViolations,
653	    criticalViolations: scanReport.criticalViolations,
654	    violationsByType,
655	    autoAppliedCount: scanReport.autoAppliedCount || 0,
656	    queuedCount: scanReport.queuedCount || 0,
657	    activeProfile: scanReport.activeProfile,
