/**
 * Governed Generate SDK — Full Inline Governance Enforcement
 * 
 * This is the canonical entry point for any LLM generation that must pass
 * through Gravito governance. It wraps the full pipeline:
 * 
 *   1. Auto-register the calling product (if external)
 *   2. Pre-generation: classify content, inject governance context
 *   3. LLM generation via safeLLM (never-throw wrapper)
 *   4. Post-generation: heuristic analysis → Gravito inline review → decision
 *   5. Verdict enforcement: pass / stabilize / block / regenerate
 *   6. Failsafe: if Gravito is down, use degraded-mode policy engine
 * 
 * Usage:
 *   const result = await governedGenerate({
 *     messages: [{ role: 'user', content: 'Write a health disclaimer' }],
 *     productId: 'troubadour-music-app',
 *     contentType: 'medical',
 *     contentRole: 'user-facing',
 *   });
 */
import { safeLLM, isFallbackResponse } from './safe-llm';
import { coProcessorPreGenerate, coProcessorPostGenerate, applyVerdict, type ContentDomain, type CoProcessorVerdict, type CoProcessorDecision } from './co-processor/index';
import { registerSurfaceIfMissing, incrementActivityCounter } from './auto-surface-registration';
import { evaluateDegradedPolicy, recordDegradedEvaluation } from './degraded-policy-engine';
import { resolveGovernanceContext, buildGovernanceInjection, recordContextResolution } from './product-context';
import { createLogger } from '../_core/logger';
import { getGovernanceBypassState, withGovernanceBypassAsync, type InvokeParams, type InvokeResult, type Message } from '../_core/llm';
import { preShapePrompt, enforce, enforceDegraded, recordGeometryEnforcement } from './geometry-controller';
import { composeDeepGeometryVerdict, type DeepGeometryVerdict } from './geometry-deep-verdict';
import { decideGeometryInfluence } from './geometry-verdict-influence';
import { decideManifoldInfluence } from './manifold-verdict-influence';
import { getManifoldSessionTrajectory } from '../emotional-geometry-runtime/geometry/manifold-session-state';
import { decideRecallInfluence } from './recall-verdict-influence';
import { isFeatureEnabled } from '../emotional-geometry-runtime/feature-flags';
import { attachCanonicalReceiptIfEnabled, type CanonicalVerdictReceipt } from './canonical-verdict-receipt';
import { selectShadowContent, classifyEnforcementOutcome } from './geometry-content-select';
import { recordGeometryShadow } from './geometry-shadow-record';
import { recordGeometryEvalCapture } from './geometry-eval-capture-record';
import { recognizeRepeatFailure, lookupRepeatFailure, type RepeatFailureRecognitionInput } from './repeat-failure-recognition';
import { recordDegradedCause } from './degraded-cause-record';
import { requestApproval, REGULATED_SURFACES, FAIL_CLOSED_ERROR } from './regulated-surface-preapproval';
import { createHash } from 'crypto';
import { unsafeCast } from '../../shared/type-bridge';
import { preGenerationHook, postGenerationHook, type GeometryPreGenerationResult, type GeometryPostGenerationResult } from '../emotional-geometry-runtime/geometry-runtime-bridge';
import { advancedPreGenerationHook, advancedPostGenerationHook } from '../neurocosmology-runtime-advanced/integration-hooks';
import { createInitialState, updateBaseDimensions, type CanonicalEmotionalState } from '../emotional-geometry-runtime/state/EmotionalState';
import { persistGeometryData } from '../emotional-geometry-runtime/session-persistence';
import { evaluateAlerts } from '../emotional-geometry-runtime/geometry-alerting';

const log = createLogger('governance');

// ============================================================================
// TYPES
// ============================================================================

export interface GovernedGenerateParams {
  /** LLM messages (system + user + assistant history) */
  messages: InvokeParams['messages'];
  /** Model override (optional — uses default if not specified) */
  model?: string;
  /** Content type for governance classification */
  contentType?: string;
  /** Content role: user-facing, internal, admin, system */
  contentRole?: 'user-facing' | 'internal' | 'admin' | 'system';
  /** Product ID for auto-registration and per-product governance */
  productId?: string;
  /** Product name (used for auto-registration) */
  productName?: string;
  /** Surface ID for governance context routing */
  surfaceId?: string;
  /** Audience type for tone calibration */
  audienceType?: 'general' | 'professional' | 'technical' | 'legal' | 'medical';
